// Core Testing Fundamentals — Part 4 (q316–420)
window.QUIZ_BANK['core-testing'] = (window.QUIZ_BANK['core-testing']||[]).concat([
{id:316,topic:'core-testing',difficulty:'intermediate',question:'In test management, what is the difference between a "test run" and a "test cycle"?',options:['They are identical terms','A test cycle is a planned set of test activities covering a scope; a test run is a single execution instance of a suite within that cycle','A test run covers all features; a test cycle covers only regression','A test cycle is automated; a test run is manual'],answer:1,explanation:'A test cycle represents the planned set of activities for a release or sprint; a test run is one execution of a specific test suite or set of test cases within the cycle.'},
{id:317,topic:'core-testing',difficulty:'intermediate',question:'What is the main benefit of "pair programming" for software quality?',options:['It halves the time to write code','Two developers working together produce code with fewer defects due to real-time peer review, catching issues before testing','It eliminates the need for unit testing','It guarantees 100% branch coverage'],answer:1,explanation:'Pair programming provides continuous code review (the navigator catches what the driver misses), resulting in fewer defects reaching QA and improved code clarity.'},
{id:318,topic:'core-testing',difficulty:'intermediate',question:'What is "impact analysis" in the context of regression testing?',options:['Assessing the business impact of found defects','Determining which areas of the system are affected by a code change to identify which regression tests need to be run','Analysing the impact of test automation on team productivity','Calculating the financial impact of a software release'],answer:1,explanation:'Impact analysis maps code changes to affected components and associated test cases, enabling teams to run only the relevant subset of regression tests rather than the full suite.'},
{id:319,topic:'core-testing',difficulty:'intermediate',question:'Which of the following is a characteristic of "acceptance criteria" for user stories?',options:['They should be vague to allow flexible implementation','They should be specific, measurable, and testable, defining the conditions under which a story is accepted as done','They should be written after development is complete','They should only be written by developers'],answer:1,explanation:'Acceptance criteria must be specific, unambiguous, and testable — forming the basis for acceptance tests and the definition of done for a user story.'},
{id:320,topic:'core-testing',difficulty:'intermediate',question:'Which performance testing type measures what happens to the application when the load is suddenly and dramatically increased (e.g., viral traffic)?',options:['Soak testing','Volume testing','Spike testing','Stress testing'],answer:2,explanation:'Spike testing simulates sudden, extreme surges in user load to verify the application handles them gracefully — critical for systems that may experience viral traffic events.'},
{id:321,topic:'core-testing',difficulty:'intermediate',question:'In test reporting, what is a "burn-down chart" used for?',options:['Showing accumulated defect density over time','Visualising the remaining testing work (test cases yet to be executed) over time within a sprint or test cycle','Showing the increase in test coverage over the project','Tracking the number of automated tests built per sprint'],answer:1,explanation:'A test burn-down chart shows the declining volume of unexecuted (or open) test cases over the cycle timeline, helping predict whether testing will be complete by the deadline.'},
{id:322,topic:'core-testing',difficulty:'intermediate',question:'What is "test-driven requirements analysis"?',options:['Deriving test cases from incomplete requirements','A collaborative technique where testers actively participate in requirements analysis by asking testability questions and identifying ambiguities early','Analysing test results to improve requirements','Having testers write the requirements'],answer:1,explanation:'Test-driven requirements analysis has testers review requirements early to identify vagueness, contradictions, and untestable statements — dramatically reducing defects that originate from poor requirements.'},
{id:323,topic:'core-testing',difficulty:'intermediate',question:'Which of the following describes "volume testing"?',options:['Testing the system at maximum concurrent users','Verifying the system can handle very large amounts of data — large databases, large files, or high-volume transactions — without failure','Testing the volume of test cases in a suite','Load testing a video streaming system'],answer:1,explanation:'Volume testing verifies the system handles large volumes of data correctly: large DB tables, large file uploads, or bulk transaction processing.'},
{id:324,topic:'core-testing',difficulty:'intermediate',question:'What is "MTBF" in reliability testing?',options:['Maximum Test Buffer Frequency','Mean Time Between Failures — the average time the system operates without failing under normal conditions','Minimum Test Backlog Forecast','Mean Test Build Frequency'],answer:1,explanation:'MTBF (Mean Time Between Failures) measures system reliability: the average operating time between consecutive failures. Higher MTBF indicates greater reliability.'},
{id:325,topic:'core-testing',difficulty:'intermediate',question:'When should static testing (reviews) ideally be performed?',options:['After all coding is complete','As early as possible in the development lifecycle, starting with requirements review','Only during the testing phase','After system testing is complete'],answer:1,explanation:'Static testing should begin at the start of the SDLC with requirements review; finding defects in requirements is far cheaper than discovering them after code has been written and tested.'},
{id:326,topic:'core-testing',difficulty:'intermediate',question:'What does "context-driven testing" emphasise?',options:['Using context-aware automation tools','That the best testing practices depend on the specific context (project, domain, team, constraints) and there are no universal best practices','Testing the application in different geographic locales','Using contextual AI to generate test cases'],answer:1,explanation:'Context-driven testing (associated with James Bach, Michael Bolton) holds that good testing is situational — what works in one context may not work in another, requiring skilled judgment over rigid processes.'},
{id:327,topic:'core-testing',difficulty:'intermediate',question:'What is "GUI testing"?',options:['Testing the programming logic through source code','Verifying that the graphical user interface of an application renders correctly and responds appropriately to user interactions','Testing the internal database queries','Load testing web application UI rendering'],answer:1,explanation:'GUI testing validates the visual interface: layout, navigation, controls, form interactions, and visual feedback — ensuring the user-facing elements work correctly on target browsers/devices.'},
{id:328,topic:'core-testing',difficulty:'intermediate',question:'What does a "test execution schedule" define?',options:['The order in which test cases will be written','The planned sequence, timing, and resource assignments for executing test cases within a test cycle','The automated CI pipeline configuration','The test data refresh schedule'],answer:1,explanation:'The test execution schedule maps test cases to time slots and resources, accounting for dependencies, environment availability, and risk priorities during a test cycle.'},
{id:329,topic:'core-testing',difficulty:'intermediate',question:'In testing, what is "testability"?',options:['The ability of testers to write tests quickly','The degree to which a system\'s design and implementation facilitate the creation, execution, and evaluation of tests — through controllability, observability, and decomposability','The number of test cases that can be automated','The ease of installing the test automation framework'],answer:1,explanation:'Testability is a quality attribute reflecting how easy it is to test a system; high testability includes observability (you can see what happens), controllability (you can set state), and decomposability (you can isolate components).'},
{id:330,topic:'core-testing',difficulty:'advanced',question:'Which of the following best describes "software testability" as an architectural quality attribute?',options:['The speed at which the test suite executes','The degree to which the software architecture enables testing through properties like controllability, observability, isolatability, and separation of concerns','The ability of the test framework to support multiple languages','The completeness of the requirements specification'],answer:1,explanation:'Architectural testability means the system was designed to be testable: clear interfaces, dependency injection, separation of concerns, logging/metrics hooks — all reducing the effort to write and run tests.'},
{id:331,topic:'core-testing',difficulty:'advanced',question:'What is "mutation score adequacy" and why does it matter?',options:['A score given to test managers for team performance','A measure of test suite effectiveness: the proportion of detectable (non-equivalent) mutants killed. Higher scores indicate the suite is better at catching real faults','A measure of code complexity that predicts defect density','The ratio of automated to manual tests'],answer:1,explanation:'Mutation score adequacy is used as a proxy for test suite effectiveness beyond code coverage; a suite with 90%+ mutation score is considered adequate for most safety-critical applications.'},
{id:332,topic:'core-testing',difficulty:'advanced',question:'In testing AI/ML systems, what is the primary challenge with the "oracle problem"?',options:['AI systems are too slow to test','For many AI/ML outputs (image recognition, NLP, recommendations), there is no deterministic correct answer — testers must use statistical measures, reference datasets, or metamorphic relations instead','AI systems cannot be integrated with test automation tools','AI systems always produce the same output for the same input'],answer:1,explanation:'AI/ML systems lack deterministic oracles; testers use golden datasets, fairness metrics, metamorphic testing relations, and statistical bounds to assess whether outputs are acceptable.'},
{id:333,topic:'core-testing',difficulty:'advanced',question:'What is "regulatory testing" and when is it mandatory?',options:['Testing required by the test team\'s internal regulations','Testing performed to demonstrate compliance with external legal regulations (FDA, CE marking, FAA, HIPAA) — mandatory for systems in regulated industries like healthcare, aerospace, and finance','Testing mandated by the development team\'s agile process','Testing required before any code review'],answer:1,explanation:'Regulatory testing verifies compliance with specific regulatory standards required in the system\'s industry; failure to pass may prevent product release (e.g., FDA 510(k), CE marking for medical devices).'},
{id:334,topic:'core-testing',difficulty:'advanced',question:'What is the purpose of "test basis review" before test design begins?',options:['To confirm the test team has enough members','To identify ambiguities, inconsistencies, testability issues, and gaps in the requirements or design documents — preventing defects from being designed into tests','To review the test automation framework selection','To review the test execution results from the previous cycle'],answer:1,explanation:'Reviewing the test basis before test design catches requirements defects (ambiguity, contradiction, missing cases) early, preventing them from being encoded into flawed test cases.'},
{id:335,topic:'core-testing',difficulty:'advanced',question:'Which of the following is a CORRECT statement about "testing shows the presence of defects"?',options:['Testing can prove the software is completely defect-free','Testing can only demonstrate that defects exist; it cannot prove their absence','If all tests pass, the software has no defects','Testing shows defects only in automated suites'],answer:1,explanation:'ISTQB principle: testing can reveal defects (presence) but a clean test run does NOT guarantee absence of defects — other defects may exist in untested paths or scenarios.'},
{id:336,topic:'core-testing',difficulty:'advanced',question:'What makes "pairwise testing" particularly powerful for configuration testing?',options:['It tests every possible hardware configuration','For systems with many configuration parameters, pairwise coverage (every pair tested once) typically detects over 70% of configuration-dependent bugs with a fraction of the tests needed for full coverage','It is faster than all other testing techniques','It only requires one test per parameter value'],answer:1,explanation:'Studies on real systems show most configuration faults are triggered by 2-way interactions; pairwise testing covers all pairs efficiently, providing good fault detection at low test count.'},
{id:337,topic:'core-testing',difficulty:'advanced',question:'What is "observability" in the context of testing microservices?',options:['The ability to monitor test execution in real time','The system\'s ability to infer internal state from external outputs — via logs, metrics, and traces — enabling testers to diagnose failures in complex distributed systems','A GDPR requirement to log all user actions','The monitoring of test infrastructure performance'],answer:1,explanation:'Observability in microservices (three pillars: logs, metrics, traces) allows testers and operators to understand system behaviour and diagnose failures even in complex distributed environments.'},
{id:338,topic:'core-testing',difficulty:'advanced',question:'What is "negative testing" specifically designed to find?',options:['Defects in database negative number handling','How the system handles invalid, unexpected, or extreme inputs — verifying it fails gracefully rather than crashing or exposing sensitive information','Performance degradation at low load','Security vulnerabilities in positive test paths'],answer:1,explanation:'Negative testing probes error-handling paths: invalid inputs, boundary violations, missing required fields — verifying the system responds with proper error messages rather than crashes or data corruption.'},
{id:339,topic:'core-testing',difficulty:'advanced',question:'In the ISO 29119 testing process model, which process group focuses on "manage the testing project"?',options:['Dynamic test process','Static test process','Test management process','Test organisation process'],answer:2,explanation:'ISO 29119-2 defines the test management process, which covers test planning, monitoring, control, and completion — the management activities that govern all testing work.'},
{id:340,topic:'core-testing',difficulty:'advanced',question:'What is "test-point analysis" (TPA) and when is it used?',options:['Analysis of test execution breakpoints in debuggers','A structured test estimation technique that assigns points to test conditions based on their complexity and environmental factors, producing an estimate of testing effort in test hours','Analysis of performance test bottlenecks','A technique for analysing test tool pricing'],answer:1,explanation:'TPA is a structured estimation method from the Netherlands that assigns size points to test conditions based on function points and risk factors, then converts to effort hours using productivity rates.'},
{id:341,topic:'core-testing',difficulty:'beginner',question:'What is the difference between "expected result" and "actual result" in a test case?',options:['They are identical','Expected result is what the system should do per the specification; actual result is what the system did when the test was run','Expected result comes from the developer; actual result comes from the tester','Actual result is always wrong; expected result is always right'],answer:1,explanation:'Expected result defines the correct system behaviour per requirements; actual result is what was observed. Discrepancy = potential defect.'},
{id:342,topic:'core-testing',difficulty:'beginner',question:'Which of the following best describes "code coverage" as a testing metric?',options:['The percentage of features tested','The percentage of source code (statements, branches, paths) exercised by the test suite','The percentage of requirements covered by test cases','The percentage of defects found per module'],answer:1,explanation:'Code coverage measures the degree to which the source code is exercised during test execution; common metrics include statement, branch, and path coverage.'},
{id:343,topic:'core-testing',difficulty:'beginner',question:'What is a "blocker defect"?',options:['A defect that only occurs in older browsers','A defect that prevents the system from being used or tested further in its current state — typically causing a crash, hang, or complete loss of core functionality','A defect that is too minor to fix','A defect in third-party code that cannot be fixed by the development team'],answer:1,explanation:'A blocker (or showstopper) is a defect with critical severity that prevents the test cycle from progressing or makes core functionality completely unavailable.'},
{id:344,topic:'core-testing',difficulty:'beginner',question:'What does "test prioritisation" help with?',options:['Writing test cases in the right order','Deciding which test cases to execute first when time or resources are limited, to maximise risk coverage early','Assigning test cases to specific testers','Organising test cases by feature module'],answer:1,explanation:'Test prioritisation orders test execution to maximise the value of early testing: running high-risk, high-impact, or recently changed areas first ensures the most important functionality is verified even if time runs out.'},
{id:345,topic:'core-testing',difficulty:'beginner',question:'What is "test churn" in automated testing?',options:['The speed at which automated tests execute','The rate at which automated tests fail due to application changes, often indicating brittleness in the automation implementation','The number of new tests added per sprint','The frequency of CI pipeline runs'],answer:1,explanation:'Test churn measures how often tests break due to non-defect changes (UI refactoring, data changes) — high churn signals brittle tests with excessive maintenance cost.'},
{id:346,topic:'core-testing',difficulty:'beginner',question:'What is an "acceptance test"?',options:['A test performed by the development team to accept a feature','A test used to determine whether a system satisfies specified acceptance criteria, typically performed by the customer or end user','An automated unit test that passes acceptance standards','A performance test that must pass before release'],answer:1,explanation:'Acceptance tests validate that the system satisfies the agreed acceptance criteria and that the customer/user accepts it as meeting their needs.'},
{id:347,topic:'core-testing',difficulty:'beginner',question:'Which of the following is TRUE about "testing in production"?',options:['It is always unsafe and should never be done','With proper safeguards (feature flags, canary deployments, synthetic monitoring), production testing can provide insights impossible to get in pre-production environments','It eliminates the need for pre-production testing','It is only applicable to mobile applications'],answer:1,explanation:'Modern practices like canary deployments, A/B testing, and synthetic monitoring enable controlled testing in production, providing real-user data that pre-production environments cannot replicate.'},
{id:348,topic:'core-testing',difficulty:'beginner',question:'What does "test scope" define?',options:['The total budget for testing activities','What will and will not be tested — the features, functions, systems, and areas included in and excluded from the test effort','The test tools that will be used','The team structure for testing'],answer:1,explanation:'Test scope defines the boundaries of the test effort: which features/components are included (in-scope) and which are excluded (out-of-scope) from testing activities.'},
{id:349,topic:'core-testing',difficulty:'beginner',question:'Which of the following is the correct ISTQB definition of a "defect"?',options:['An imperfection in a work product that can cause a failure','Any negative feedback from a user','A failed test case','A performance regression'],answer:0,explanation:'ISTQB defines a defect (bug, fault) as an imperfection or deficiency in a work product — a flaw in code, requirements, or design that may cause a failure when the work product is used.'},
{id:350,topic:'core-testing',difficulty:'beginner',question:'Which testing type specifically verifies that recently changed code has not broken previously working functionality?',options:['Smoke testing','Exploratory testing','Regression testing','Load testing'],answer:2,explanation:'Regression testing re-executes a subset of previously passing tests after code changes to detect unintended breakage of existing functionality.'},
{id:351,topic:'core-testing',difficulty:'intermediate',question:'What is "specification-based" testing?',options:['Deriving tests from the source code structure','Deriving test cases from the system\'s requirements, specifications, or models — testing from the outside in without knowledge of internal implementation','Testing using formal specification languages only','Writing tests before specifications are complete'],answer:1,explanation:'Specification-based (black-box) testing designs test cases from documented requirements or specifications; it validates that specified behaviour is correctly implemented.'},
{id:352,topic:'core-testing',difficulty:'intermediate',question:'In which testing lifecycle activity are "test conditions" identified?',options:['Test closure','Test implementation','Test analysis','Test execution'],answer:2,explanation:'Test analysis examines the test basis and identifies testable conditions: specific items, events, and characteristics that need to be tested.'},
{id:353,topic:'core-testing',difficulty:'intermediate',question:'What is a "test design technique"?',options:['A tool for writing automated test scripts','A procedure for deriving and selecting test cases from a test basis — transforming test conditions into actual test cases with specific inputs and expected outputs','A reporting format for test results','A methodology for test team organisation'],answer:1,explanation:'Test design techniques (EP, BVA, decision tables, state transitions) provide systematic procedures for selecting test inputs and expected outputs from the test basis.'},
{id:354,topic:'core-testing',difficulty:'intermediate',question:'Which of the following metrics is MOST useful for assessing test progress during execution?',options:['Total lines of code','Test execution rate (% complete) and pass/fail trend over time','Number of requirements in the specification','Number of automated frameworks installed'],answer:1,explanation:'During execution, tracking the % of tests executed and the trend in pass/fail rates provides the most actionable quality signal for test managers and stakeholders.'},
{id:355,topic:'core-testing',difficulty:'intermediate',question:'What is the "IEEE 29119" standard primarily about?',options:['Software coding standards','Software performance benchmarking','Software testing — providing a complete standard for testing concepts, processes, documentation, and techniques','Agile project management practices'],answer:2,explanation:'ISO/IEC/IEEE 29119 is a comprehensive international standard for software testing, encompassing: concepts (Part 1), processes (Part 2), documentation (Part 3), techniques (Part 4), and keyword-driven testing (Part 5).'},
{id:356,topic:'core-testing',difficulty:'intermediate',question:'What is "risk identification" in test planning?',options:['Finding defects in the software','The process of identifying potential problems that could impact the quality of the product (product risks) or the success of the testing effort (project risks)','Identifying test cases that cover all risks','Documenting known defects from previous releases'],answer:1,explanation:'Risk identification is a proactive process during test planning that identifies product risks (potential failures) and project risks (resource, schedule, environment) to inform testing strategy.'},
{id:357,topic:'core-testing',difficulty:'intermediate',question:'Which of the following test artifacts is created DURING test execution?',options:['Test plan','Test case','Test log / test execution record','RTM'],answer:2,explanation:'The test log (execution record) is created during and after test execution, capturing the actual results, timestamps, and any deviations observed for each executed test case.'},
{id:358,topic:'core-testing',difficulty:'intermediate',question:'What does "defect age" measure?',options:['How long the defect has been in the codebase since its introduction','The time elapsed from when a defect was logged to when it is closed or fixed','The age of the software version containing the defect','The number of days since the last regression test'],answer:1,explanation:'Defect age measures the elapsed time from defect logging to closure; high average defect age indicates bottlenecks in the fix-test cycle.'},
{id:359,topic:'core-testing',difficulty:'intermediate',question:'Which of the following is a key responsibility of a test manager?',options:['Writing all test cases personally','Managing people, planning and controlling test activities, communicating quality status to stakeholders, and ensuring testing meets project objectives','Executing all automated test scripts','Performing code reviews'],answer:1,explanation:'The test manager plans, organises, and controls the test effort; manages the test team; communicates quality status; and ensures testing activities align with project goals.'},
{id:360,topic:'core-testing',difficulty:'intermediate',question:'What is "operational profile testing"?',options:['Testing user authentication and access profiles','Using statistical models of actual system usage patterns to guide test case selection — focusing testing effort on the most frequently used operations','Testing the application\'s configuration profile system','Load testing with a realistic production user mix'],answer:1,explanation:'Operational profile testing allocates testing effort proportionally to how users will actually use the system, maximising defect detection in high-usage paths and improving field reliability.'},
{id:361,topic:'core-testing',difficulty:'advanced',question:'What is "equivalence partitioning" also referred to as in some literature?',options:['Boundary testing','Equivalence class partitioning (ECP)','Path partitioning','Partition coverage testing'],answer:1,explanation:'Equivalence partitioning is formally called equivalence class partitioning (ECP) in some ISTQB and academic literature — the terms are interchangeable.'},
{id:362,topic:'core-testing',difficulty:'advanced',question:'In white-box testing, "MC/DC" stands for:',options:['Multiple Condition / Decision Coverage','Modified Condition / Decision Coverage','Minimal Code / Decision Coverage','Maximum Condition / Decision Coverage'],answer:1,explanation:'MC/DC (Modified Condition/Decision Coverage) requires that each condition in a decision independently affects the decision outcome; it is mandated for safety-critical aviation software (DO-178C Level A).'},
{id:363,topic:'core-testing',difficulty:'advanced',question:'What is "traceability matrix" used for in testing?',options:['Tracking defects through the fix cycle','Creating a mapping between requirements, test cases, and defects to demonstrate coverage, support change impact analysis, and satisfy regulatory compliance','Measuring test execution velocity','Organising automated tests into suites'],answer:1,explanation:'An RTM provides bidirectional traceability: from requirements to tests (forward traceability) and from tests to requirements (backward traceability), enabling coverage analysis and compliance demonstration.'},
{id:364,topic:'core-testing',difficulty:'advanced',question:'What does "testing quadrant Q2" in Brian Marick\'s Agile Testing Quadrants contain?',options:['Unit tests and component tests','Functional tests, story tests, and prototype tests that are business-facing and support development','Performance tests and security tests','Exploratory testing and usability testing'],answer:1,explanation:'Q2 (Business-facing, Support Development) contains functional acceptance tests, story tests, and business-readable specifications — tests that validate business requirements during development.'},
{id:365,topic:'core-testing',difficulty:'advanced',question:'Which of the following is a correct description of "structural testing" adequacy criteria?',options:['The application passes all performance benchmarks','A structural adequacy criterion (statement, branch, MC/DC) is met when the test suite achieves the required coverage percentage on the specified code structure elements','All functional requirements are covered by tests','All defects found are critical severity'],answer:1,explanation:'Structural adequacy criteria define minimum acceptable code coverage thresholds; meeting them (e.g., 80% branch coverage) demonstrates the test suite exercises sufficient code structure.'},
{id:366,topic:'core-testing',difficulty:'advanced',question:'What is "regression test selection" in the context of large test suites?',options:['Randomly selecting 10% of tests to run','Intelligently choosing a minimal subset of regression tests that covers all code paths affected by recent changes — using techniques like test impact analysis or code change tracing','Selecting only the newest tests for regression','Running regression tests in alphabetical order'],answer:1,explanation:'Regression test selection (RTS) techniques minimise regression suite execution time by including only tests that exercise code paths touched by recent commits, using code change tracing or call graph analysis.'},
{id:367,topic:'core-testing',difficulty:'advanced',question:'What is "test data provisioning" in enterprise testing?',options:['Writing test data directly into application code','The automated or semi-automated process of creating, configuring, and delivering test data to test environments on demand — including masking PII and managing data lifecycle','Manually entering test data before each test run','Using production backups as test data without modification'],answer:1,explanation:'Enterprise TDP automates the creation and delivery of fit-for-purpose test data: synthetic data generation, sub-setting, masking, and environment refresh to support parallel testing without data contention.'},
{id:368,topic:'core-testing',difficulty:'advanced',question:'In testing, what is a "monitor" (or "test monitor")?',options:['A hardware display used by the tester','A tool or script that observes system state, collects metrics, and captures output during test execution — providing data needed to evaluate test results','The project manager overseeing the test team','A CI/CD pipeline stage that runs tests automatically'],answer:1,explanation:'A test monitor captures system state and output during execution (logs, performance counters, network traffic) to support result analysis; it is a component of the test harness.'},
{id:369,topic:'core-testing',difficulty:'advanced',question:'What is "specification coverage" as distinct from "code coverage"?',options:['Specification coverage measures how many requirements exist in the spec document','Specification coverage measures the proportion of testable requirements that have been exercised by tests; code coverage measures the proportion of code statements/branches exercised','They measure the same thing from different perspectives','Specification coverage is for manual tests; code coverage is for automated tests'],answer:1,explanation:'Specification coverage: requirements tested / total requirements. Code coverage: code executed / total code. Both are important and complementary — meeting code coverage does not guarantee requirements coverage.'},
{id:370,topic:'core-testing',difficulty:'advanced',question:'What is the primary challenge of testing "serverless" architecture (e.g., AWS Lambda)?',options:['Serverless functions cannot be unit tested','The ephemeral, event-driven, and distributed nature makes end-to-end testing difficult; cold starts, event source integration, timeout limits, and environment parity are key challenges','Serverless systems do not require testing','Serverless functions run too fast to test'],answer:1,explanation:'Serverless testing faces: cold start performance variability, difficulty replicating cloud event sources locally, timeout constraints, distributed debugging, and environment drift between local and cloud.'},
{id:371,topic:'core-testing',difficulty:'beginner',question:'What is the main purpose of "smoke testing" in a CI/CD context?',options:['To test the performance of the build server','To quickly validate that the critical path of the build works before investing in full test execution','To replace all other forms of testing','To detect memory leaks in the application'],answer:1,explanation:'In CI/CD, smoke tests run immediately after deployment to verify the build is stable enough for further testing — a quick sanity check of core functionality.'},
{id:372,topic:'core-testing',difficulty:'beginner',question:'What is a "test scenario"?',options:['A description of a security attack vector','A narrative description of a real-world situation that a user might encounter, used to derive one or more test cases','A list of all possible test inputs','The expected output of a performance test'],answer:1,explanation:'A test scenario describes a high-level user story or real-world use case; from it, specific test cases with exact steps and inputs are derived.'},
{id:373,topic:'core-testing',difficulty:'beginner',question:'Which of the following activities comes AFTER test design in the testing process?',options:['Test planning','Test analysis','Test implementation','Test basis review'],answer:2,explanation:'The ISTQB test process sequence is: Planning → Monitoring & Control → Analysis → Design → Implementation → Execution → Closure. Implementation follows design.'},
{id:374,topic:'core-testing',difficulty:'beginner',question:'What does "test automation" primarily do differently from manual testing?',options:['Automation covers more requirements','Automation executes test cases using software tools without human interaction, enabling repeatable, fast execution at scale','Automation finds more types of defects','Automation is always more thorough'],answer:1,explanation:'Automated testing executes pre-coded test scripts without manual intervention, enabling fast, repeatable execution of regression suites at a scale impossible with manual execution.'},
{id:375,topic:'core-testing',difficulty:'beginner',question:'Which of the following is a goal of "non-functional testing"?',options:['Verify that the login feature works','Verify that the system meets performance, security, scalability, and usability requirements','Verify that all functional requirements are covered','Verify that no defects remain in the database module'],answer:1,explanation:'Non-functional testing evaluates how well the system performs its functions under various conditions: speed, scalability, security, reliability, and usability — not just whether the functions work.'},
{id:376,topic:'core-testing',difficulty:'intermediate',question:'What is the purpose of "test case review" before test execution?',options:['To speed up test execution','To verify that test cases are correct, complete, unambiguous, traceable to requirements, and executable by any tester before time is invested executing them','To assign test cases to testers','To estimate testing effort'],answer:1,explanation:'Pre-execution test case reviews catch errors in test design: incorrect expected results, untestable steps, missing coverage of requirements, and ambiguous instructions — before wasting execution time.'},
{id:377,topic:'core-testing',difficulty:'intermediate',question:'What does "traceability" between test cases and requirements ensure?',options:['All test cases are automated','No requirement is left untested and any requirement change\'s test impact can be quickly identified','All defects are linked to test cases','Tests are executed in requirement order'],answer:1,explanation:'Traceability enables two key capabilities: completeness check (every requirement has at least one test) and impact analysis (if requirement changes, identify which tests are affected).'},
{id:378,topic:'core-testing',difficulty:'intermediate',question:'In what way does "BDD" (Behaviour Driven Development) support testing?',options:['BDD replaces all other testing types','BDD creates business-readable scenarios in Given/When/Then format that serve as both requirements and executable acceptance tests, closing the gap between business and technical teams','BDD only supports unit testing','BDD is only applicable to UI testing'],answer:1,explanation:'BDD\'s Given/When/Then scenarios are understandable by non-technical stakeholders and directly map to executable automated acceptance tests (Cucumber, SpecFlow), creating living documentation.'},
{id:379,topic:'core-testing',difficulty:'intermediate',question:'What is "test harness setup" in automated testing?',options:['Installing the test management tool','Configuring the complete execution environment: test framework, test data, stubs/mocks, CI integration, and reporting tools needed to run automated tests reliably','Documenting the test execution schedule','Training the test team on the automation framework'],answer:1,explanation:'Test harness setup prepares the full automated test execution environment: framework initialisation, test data seeding, mock/stub configuration, environment variables, and reporting pipeline.'},
{id:380,topic:'core-testing',difficulty:'intermediate',question:'What is "test independence" and why does it prevent bias?',options:['Tests run in separate processes to improve performance','Having someone other than the author test a work product reduces the author\'s confirmation bias, increasing the likelihood of finding defects the author overlooked','Test cases that do not depend on each other for data','Automated tests that run without human oversight'],answer:1,explanation:'Test independence ensures a fresh perspective: independent testers approach work products without the author\'s assumptions and blind spots, leading to higher defect detection rates.'},
{id:381,topic:'core-testing',difficulty:'advanced',question:'What is "test oracle automation" and why is it difficult to achieve?',options:['Automating the test scheduling process','Automating the determination of expected results, which is difficult because expected outputs often require human judgment, external reference systems, or mathematical derivation','Automating all manual tests','Using Oracle DB for test management'],answer:1,explanation:'Automated oracles programmatically determine expected results; challenges include: no formal specification, complex business logic, non-deterministic outputs, and the oracle problem for complex domains like AI/ML.'},
{id:382,topic:'core-testing',difficulty:'advanced',question:'Which of the following describes "chaos monkey" testing?',options:['Running tests in a random order to find sequencing defects','A Netflix-originated service that randomly terminates production instances to verify the system continues functioning when components unexpectedly fail','A fuzz testing technique for mobile applications','Random test case generation from requirements'],answer:1,explanation:'Netflix\'s Chaos Monkey randomly terminates virtual machine instances in production to verify the system handles unexpected failures — a key chaos engineering practice for resilience validation.'},
{id:383,topic:'core-testing',difficulty:'advanced',question:'What is "dark launch" testing in continuous delivery?',options:['Testing performed at night to avoid impacting users','Deploying new code to production and routing real traffic through it in the background (without exposing results to users) to test performance and behaviour at scale','Testing features in dark mode UI','A security testing technique using obfuscated deployments'],answer:1,explanation:'Dark launches deploy new code paths alongside the current version; real production traffic is processed by both, but only the old version\'s results are shown to users — enabling production-scale performance validation without user impact.'},
{id:384,topic:'core-testing',difficulty:'advanced',question:'What does "test amplification" mean in modern testing research?',options:['Making test cases more impactful by increasing assertion count','Using automated tools to enhance existing test suites by generating new assertions, new inputs, or new test cases based on code changes — amplifying the coverage of a human-written seed suite','Increasing test execution speed through parallelism','Amplifying defect descriptions for better developer understanding'],answer:1,explanation:'Test amplification tools (e.g., DSpot) take a human-authored test suite and automatically generate stronger variants with additional inputs and assertions, improving coverage without manual effort.'},
{id:385,topic:'core-testing',difficulty:'advanced',question:'What is "shift-left security testing" (also called DevSecOps)?',options:['Moving security analysts earlier in the hiring process','Integrating security testing activities (SAST, SCA, threat modelling, DAST) into the development and CI/CD pipeline stages rather than waiting until release','Testing security patches after deployment','Performing security testing only on the left-hand side of the architecture'],answer:1,explanation:'DevSecOps (shift-left security) embeds security practices — static analysis, dependency scanning, threat modelling, dynamic scanning — into every CI/CD stage to find and fix security issues early when they are cheapest to remediate.'},
{id:386,topic:'core-testing',difficulty:'beginner',question:'What is the difference between a "test case" and a "test script"?',options:['They are identical documents','A test case defines what to test and expected results; a test script is a more detailed, step-by-step execution guide (or code) derived from the test case','A test script is written before the test case','Test cases are automated; test scripts are manual'],answer:1,explanation:'A test case defines the testing intent (preconditions, steps, expected results); a test script provides detailed execution instructions or automated code derived from the test case.'},
{id:387,topic:'core-testing',difficulty:'beginner',question:'What is "defect tracking" in quality management?',options:['Tracking which developers write the most code','The process of recording, monitoring, and managing the status of defects throughout their lifecycle from discovery to closure','Tracking test execution time','Monitoring server performance during testing'],answer:1,explanation:'Defect tracking involves logging defects, assigning them, tracking fix progress, managing status transitions, and reporting defect metrics — essential for visibility into quality status.'},
{id:388,topic:'core-testing',difficulty:'beginner',question:'Which of the following is a valid reason for "deferring" a defect?',options:['The developer cannot reproduce it','The defect is low severity/priority and the team agrees it is not worth fixing in the current sprint/release','The tester made a mistake in the test case','The defect is already fixed in a newer version'],answer:1,explanation:'Deferral is appropriate when a confirmed defect has low risk impact and the team\'s limited resources are better spent on higher-priority issues in the current cycle.'},
{id:389,topic:'core-testing',difficulty:'beginner',question:'What does a "pass" result on a test case indicate?',options:['The software is completely bug-free','The actual result matches the expected result for that specific test case','The test case was executed very quickly','The tester was satisfied with the feature'],answer:1,explanation:'A pass indicates the system under test produced the expected output for the given inputs, meaning that specific test case\'s conditions were met correctly.'},
{id:390,topic:'core-testing',difficulty:'beginner',question:'What is the key input to the "test design" activity?',options:['The test execution report from the previous release','Test conditions derived during test analysis, along with the test basis and coverage criteria','The defect backlog from the development team','The test automation framework documentation'],answer:1,explanation:'Test design takes the identified test conditions (from analysis) and derives specific test cases with concrete inputs, execution steps, expected results, and coverage targets.'},
{id:391,topic:'core-testing',difficulty:'intermediate',question:'What is "regression test optimisation"?',options:['Writing optimised (fast) regression tests','Selecting, prioritising, and minimising the regression test suite over time to maintain fast execution while preserving fault detection capability','Optimising the CI server configuration for faster test runs','Replacing manual regression tests with automated ones'],answer:1,explanation:'Regression test optimisation removes redundant/obsolete tests, prioritises high-value tests, and uses test impact analysis to minimise suite size while maintaining or improving defect detection.'},
{id:392,topic:'core-testing',difficulty:'intermediate',question:'What is "release testing" in software testing?',options:['Testing performed on the final release build to ensure it is ready for production deployment','Testing that verifies the CI release pipeline functions correctly','A test performed by the release manager','Testing only the release notes for accuracy'],answer:0,explanation:'Release testing is the final testing phase performed on the release candidate build to verify it meets quality standards and is fit for production — often including smoke, regression, and UAT.'},
{id:393,topic:'core-testing',difficulty:'intermediate',question:'Which of the following is a benefit of "behaviour-driven development" (BDD) specifically for testing?',options:['It eliminates the need for unit testing','Acceptance criteria written as BDD scenarios are directly executable as automated acceptance tests using tools like Cucumber, creating living documentation','It ensures 100% code coverage automatically','BDD is only applicable to API testing'],answer:1,explanation:'BDD scenarios in Gherkin are human-readable AND machine-executable: they serve as both specifications and automated acceptance tests, keeping documentation and tests in sync.'},
{id:394,topic:'core-testing',difficulty:'intermediate',question:'In test automation, what is "test isolation"?',options:['Running tests on isolated servers','Ensuring each automated test is completely independent — has its own setup/teardown, does not share state with other tests, and can run in any order','Using virtual machines for test execution','Separating unit tests from integration tests'],answer:1,explanation:'Test isolation means each test owns its data setup and cleanup, uses no shared mutable state, and passes or fails independently of other tests — preventing cascading failures.'},
{id:395,topic:'core-testing',difficulty:'intermediate',question:'What does "test monitoring" focus on during test execution?',options:['Monitoring the test tools for software updates','Tracking actual progress against the test plan, collecting metrics (pass rate, defect rate, coverage), and identifying deviations that require corrective action','Monitoring developer code commits','Observing user behaviour in production'],answer:1,explanation:'Test monitoring continuously compares actual test execution progress against planned progress, detects deviations (blocked tests, failing trends), and provides data for control decisions.'},
{id:396,topic:'core-testing',difficulty:'intermediate',question:'What is "use case testing"?',options:['Testing the use case diagram in UML tools','Designing test cases from use case descriptions to verify each scenario (main flow, alternative flows, exception flows) works correctly from an end-user perspective','Testing the system\'s API use cases only','Testing use cases in the requirements backlog'],answer:1,explanation:'Use case testing derives test cases from use case specifications: one test for the main success scenario, additional tests for each alternative and exception flow.'},
{id:397,topic:'core-testing',difficulty:'intermediate',question:'Which of the following is NOT a typical component of a test plan?',options:['Testing objectives','Test scope and out-of-scope areas','Resource and schedule plan','Detailed code design for each module'],answer:3,explanation:'Detailed code design is a development artefact. A test plan contains: objectives, scope, approach, resources, schedule, risks, entry/exit criteria, and responsibilities — not implementation design.'},
{id:398,topic:'core-testing',difficulty:'intermediate',question:'What is "technical debt" in the context of testing?',options:['Outstanding invoices for test tools','Accumulated shortcuts in test quality — poor test data, missing automation, inadequate coverage — that build up future risk requiring remediation','The developer team\'s outstanding feature backlog','Old test cases that are no longer relevant'],answer:1,explanation:'Testing technical debt includes low coverage, poor test data management, untested edge cases, and missing automation — shortcuts that were accepted to hit deadlines but create ongoing quality risk.'},
{id:399,topic:'core-testing',difficulty:'advanced',question:'What is "conformance testing"?',options:['Testing that the test team conforms to ISTQB standards','Verifying that a product or implementation conforms to a specific standard, protocol, or specification — common in networking, data formats, and regulatory domains','Testing that configurations conform to naming conventions','Performance testing that conforms to SLA requirements'],answer:1,explanation:'Conformance testing (standards testing) verifies that an implementation precisely meets a defined technical standard (e.g., HTTP/2 conformance, POSIX compliance, HL7 FHIR conformance).'},
{id:400,topic:'core-testing',difficulty:'advanced',question:'What is "risk mitigation" in test planning?',options:['Removing all risks from the project','Defining specific actions (additional tests, more thorough coverage, additional environments) to reduce the probability or impact of identified product and project risks','Mitigating the risk of the test team being unavailable','Automating all test cases to reduce manual risk'],answer:1,explanation:'Risk mitigation strategies in testing include: increasing test depth for high-risk areas, adding dedicated performance/security testing, implementing monitoring, and contingency planning for project risks.'},
{id:401,topic:'core-testing',difficulty:'advanced',question:'What does "shift-left security" specifically require test teams to do differently?',options:['Hire security specialists only at the testing stage','Integrate SAST tools in the IDE, include OWASP threat modelling in requirements, and embed dependency scanning (SCA) and DAST in the CI/CD pipeline from the first sprint','Test security only before production release','Perform penetration testing in every sprint'],answer:1,explanation:'Shift-left security operationalises security throughout the SDLC: developer SAST in IDE, automated SCA in CI, DAST in staging, threat modelling in design — rather than a single pentest before release.'},
{id:402,topic:'core-testing',difficulty:'advanced',question:'What is "testing in isolation" for microservices?',options:['Running microservice tests on separate cloud providers','Unit and component testing each microservice with all external dependencies mocked or stubbed, verifying service logic independently before integration','Testing one microservice at a time in production','Separating test environments for each team'],answer:1,explanation:'Microservice isolation testing uses service virtualisation or mocks to replace all downstream/upstream dependencies, enabling teams to test each service\'s logic independently and in parallel.'},
{id:403,topic:'core-testing',difficulty:'advanced',question:'What is the purpose of "test environment parity"?',options:['All test environments must use the same hardware brand','Ensuring test environments mirror production configuration as closely as possible to prevent environment-specific defects from escaping to production','Requiring all team members to use the same OS','Keeping all test environment passwords the same'],answer:1,explanation:'Environment parity minimises the "works in test, fails in prod" problem by ensuring configuration, middleware versions, data volumes, and network topology align with production.'},
{id:404,topic:'core-testing',difficulty:'advanced',question:'What is "synthetic data generation" in test data management?',options:['Generating test cases from requirements automatically','Programmatically creating realistic but fictitious test data that mimics production data characteristics without containing real personal information — resolving GDPR/privacy constraints','Generating test results synthetically to save execution time','Creating dummy requirements for test case design practice'],answer:1,explanation:'Synthetic data generation creates realistic test datasets (using tools like Faker, Mockaroo, or custom generators) that reflect production data patterns, volumes, and distributions without exposing real PII.'},
{id:405,topic:'core-testing',difficulty:'advanced',question:'What does "test effectiveness" measure?',options:['How fast tests execute','The ability of the test suite to detect real defects — measured as the proportion of defects found before release vs total defects (pre + post release)','The number of test cases in the suite','The cost per test case executed'],answer:1,explanation:'Test effectiveness (often measured as DRE - Defect Removal Efficiency) quantifies how well testing catches defects before release: DRE = pre-release defects / (pre-release + post-release defects) × 100.'},
{id:406,topic:'core-testing',difficulty:'advanced',question:'In continuous testing, what is the role of "service virtualization"?',options:['Virtualising test server hardware to reduce costs','Simulating dependent services (APIs, databases, legacy systems) that are unavailable, slow, or cost-prohibitive, enabling continuous automated testing even when real dependencies are absent','Creating virtual test accounts on production systems','Virtualising test environments for parallel execution'],answer:1,explanation:'Service virtualisation allows continuous testing pipelines to run without real dependent services by providing behavioural simulations — critical when third-party services have limited test environments or usage costs.'},
{id:407,topic:'core-testing',difficulty:'advanced',question:'What is the difference between "validation" and "verification" in ISO 9000?',options:['They are identical in ISO 9000','Verification: confirmation by objective evidence that specified requirements have been fulfilled. Validation: confirmation that requirements for a specific intended use/application have been fulfilled','Validation is done during development; verification is done after release','Verification uses dynamic testing; validation uses static testing only'],answer:1,explanation:'ISO 9000: Verification = "are we building it right?" (conformance to specification). Validation = "are we building the right thing?" (fitness for intended use). Both are required for complete quality assurance.'},
{id:408,topic:'core-testing',difficulty:'advanced',question:'What is "safety-critical testing" and what distinguishes it from commercial testing?',options:['Testing safety features like login security','Testing systems where failures could cause loss of life or serious harm, requiring higher rigour, formal methods, extensive documentation, and meeting standards like DO-178C, IEC 61508, or ISO 26262','Testing with extra care to avoid crashes','Testing performed by a dedicated safety team'],answer:1,explanation:'Safety-critical testing (avionics, medical devices, automotive) requires formal verification methods, exhaustive coverage criteria (MC/DC), rigorous documentation, independent verification, and regulatory approval — far beyond typical commercial testing practice.'},
{id:409,topic:'core-testing',difficulty:'advanced',question:'What is "test oracle derivation" in automated testing?',options:['Creating automated tests from Oracle Database queries','The process of determining and encoding the expected correct outputs for test cases into automated assertions — the hardest part of automation for complex systems','Deriving test cases from Oracle\'s testing documentation','Selecting an automated testing tool'],answer:1,explanation:'Oracle derivation is computing what the correct answer should be for each test input; for complex systems this requires formalisation of specifications, mathematical derivation, or reference implementation comparison.'},
{id:410,topic:'core-testing',difficulty:'advanced',question:'In testing distributed systems, what is "eventual consistency testing"?',options:['Testing that all tests eventually pass','Verifying that a distributed system, which allows temporary data inconsistency across nodes, converges to a consistent state within acceptable timeframes under various failure scenarios','Testing the consistency of test execution environments','Ensuring test data is eventually cleaned up after execution'],answer:1,explanation:'Eventual consistency testing verifies that distributed systems (Cassandra, DynamoDB) correctly converge to consistent state after a partition heals or network delay resolves — critical for NoSQL and microservices architectures.'},
{id:411,topic:'core-testing',difficulty:'beginner',question:'What is the relationship between "severity" and "priority" in defect management?',options:['They are always equal','They are independent: a cosmetic bug might be high priority for a demo; a severe crash in a rarely used feature might be low priority','Priority is always higher than severity','Severity determines priority automatically'],answer:1,explanation:'Severity and priority are independent: a critical crash in a rarely-used internal admin feature might be low business priority, while a minor typo on the homepage might be high priority for brand reasons.'},
{id:412,topic:'core-testing',difficulty:'beginner',question:'What does it mean when a test case result is "inconclusive"?',options:['The test passed with minor issues','The test outcome cannot be determined as pass or fail — often due to environmental issues, ambiguous expected results, or the system being in an inconsistent state','The test case was executed in the wrong environment','The tester was unsure of the steps'],answer:1,explanation:'An inconclusive result indicates the test could not produce a definitive pass/fail — common when the environment misbehaves, expected results are ambiguous, or a prerequisite was not met.'},
{id:413,topic:'core-testing',difficulty:'beginner',question:'Which of the following is an advantage of "exploratory testing" over scripted testing?',options:['Exploratory testing always finds more defects than scripted testing in all scenarios','Exploratory testing adapts in real time based on what the tester learns, finding defects in unanticipated scenarios that pre-scripted tests would never reach','Exploratory testing produces more documentation','Exploratory testing is faster to set up automation for'],answer:1,explanation:'Exploratory testing\'s real-time adaptation enables discovery of defects in unexpected scenarios — complex user interactions, unusual sequences, or emergent system behaviour — that scripted tests rarely reach.'},
{id:414,topic:'core-testing',difficulty:'beginner',question:'What is a "critical path" test in the context of regression testing?',options:['Tests that cover all possible code paths','Tests that verify the most important, frequently used functionality that would have the highest impact if broken','Tests run in parallel on the CI server','Tests that require administrator privileges'],answer:1,explanation:'Critical path tests cover the system\'s most business-critical workflows; they are always included in regression suites because their failure would have immediate, severe user/business impact.'},
{id:415,topic:'core-testing',difficulty:'beginner',question:'What is meant by "reproducible defect"?',options:['A defect that occurs multiple times in different modules','A defect that can be consistently triggered by following specific documented steps every time','A defect that the developer can reproduce but the tester cannot','A defect pattern that occurs in multiple products'],answer:1,explanation:'A reproducible defect consistently occurs when its documented steps are followed; reproducibility is essential for developers to locate, diagnose, and fix the underlying fault.'},
{id:416,topic:'core-testing',difficulty:'intermediate',question:'In which SDLC model would you find dedicated testing phases that only begin after the development phase is complete?',options:['Agile Scrum','V-model','Waterfall','Spiral model'],answer:2,explanation:'The traditional Waterfall model sequences phases sequentially: requirements → design → development → testing → deployment; testing begins only after development is complete — a key limitation compared to modern iterative approaches.'},
{id:417,topic:'core-testing',difficulty:'intermediate',question:'What is a "test charter" in session-based test management (SBTM)?',options:['A legal document authorising testing activities','A focused mission statement for an exploratory testing session: what to test, what information to gather, and any specific focus areas or risks to investigate','The overall test strategy document for the project','A certification document for ISTQB-certified testers'],answer:1,explanation:'In SBTM, a charter provides the purpose and focus for a time-boxed exploratory session, guiding the tester without restricting their judgment about where to explore.'},
{id:418,topic:'core-testing',difficulty:'intermediate',question:'What does "test condition identification" produce?',options:['A list of test execution results','A list of specific testable items (conditions) derived from the test basis that will form the basis for test case design','A schedule for test execution','A list of defects to fix before testing begins'],answer:1,explanation:'Test condition identification analyses the test basis and produces a list of testable aspects (e.g., "field accepts up to 255 characters", "user cannot access admin without authentication") that guide test case design.'},
{id:419,topic:'core-testing',difficulty:'intermediate',question:'Which of the following is an example of a "quality characteristic" tested by non-functional testing?',options:['The login button redirects to the correct dashboard','The search function returns relevant results','The application handles 10,000 concurrent users without degrading response time','The error message displays when entering an invalid email'],answer:2,explanation:'Handling concurrent users without degradation is a performance/scalability non-functional quality characteristic — not a functional behaviour, but a quality of how well the function performs.'},
{id:420,topic:'core-testing',difficulty:'advanced',question:'What is the "ice cream cone anti-pattern" in test automation?',options:['A problem with frozen test data','An anti-pattern where the test pyramid is inverted: many slow, fragile UI tests at the base, few integration tests, and minimal unit tests — resulting in slow, unreliable CI pipelines','A pattern where tests run too slowly in cold environments','An anti-pattern where test data is reused across too many tests'],answer:1,explanation:'The ice cream cone anti-pattern (inverse of the test pyramid) has excessive UI/E2E tests and minimal unit tests, creating slow, brittle pipelines that give delayed and unreliable feedback.'}
]);
